<style>
.df-workspace{max-width:1800px;margin:auto;color:#17243c}.df-page-hero{background:linear-gradient(120deg,#0b1c40,#173b71);border-radius:20px;padding:32px 36px;color:#fff;display:flex;align-items:center;justify-content:space-between;gap:24px}.df-eyebrow{font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;font-weight:700}.df-page-hero .df-eyebrow{color:#c7d9f0}.df-page-hero h1{font-size:clamp(1.45rem,2.4vw,2rem);line-height:1.3;margin:8px 0 12px}.df-page-hero p{margin:0;color:#d2dff2;max-width:820px}.df-page-hero>.btn{flex-shrink:0;border-radius:12px;padding:13px 18px}.df-company-context{display:flex;align-items:center;gap:16px;padding:20px 8px;flex-wrap:wrap;font-size:.9rem}.df-company-context>span{color:#68758a}.df-company-badge{background:#e7effa;border:1px solid #d1deef;color:#244875;padding:6px 12px;border-radius:20px;font-weight:600}.df-workflow-panel{background:#fff;border:1px solid #e0e7f0;border-radius:20px;padding:30px;box-shadow:0 10px 30px #172e5110}.df-section-heading{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:28px}.df-section-heading h2{font-size:1.3rem;margin:5px 0 8px}.df-section-heading p{color:#768197;font-size:.9rem;margin:0;max-width:440px}.df-workflow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:27px;list-style:none;padding:0;margin:0}.df-workflow-step{--step-color:#c29bbb;--step-bg:#f9f3f9;min-width:0}.df-workflow-step-2{--step-color:#b982b7;--step-bg:#f7f0f8}.df-workflow-step-3{--step-color:#88869f;--step-bg:#f0f0f7}.df-workflow-step-4{--step-color:#18376b;--step-bg:#eceff7}.df-step-circle{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;aspect-ratio:1;border-radius:50%;border:6px solid var(--step-color);background:var(--step-bg);padding:28px 21px;text-align:center;position:relative;color:#1f2633;text-decoration:none;box-shadow:inset 0 0 0 6px #ffffff80;transition:transform .18s,box-shadow .18s}.df-step-circle:focus-visible{outline:3px solid #2389d2;outline-offset:5px}.df-step-circle:hover{color:#142f58;transform:translateY(-4px);box-shadow:0 12px 22px #1b365522}.df-workflow-step:not(:last-child) .df-step-circle:after{content:"";position:absolute;right:-30px;top:calc(50% - 29px);width:0;height:0;border-top:29px solid transparent;border-bottom:29px solid transparent;border-left:32px solid var(--step-color);z-index:1}.df-step-number{font-size:.72rem;letter-spacing:.12em;font-weight:800;color:var(--step-color)}.df-step-title{font-size:clamp(1rem,1.5vw,1.45rem);font-weight:700;line-height:1.28}.df-workflow-step h3{font-size:.88rem;font-weight:700;line-height:1.5;margin:23px 0 14px;color:#526179}.df-step-details{list-style:none;margin:23px 0 0;padding:0;display:flex;flex-direction:column;gap:10px}.df-step-details li{display:flex;gap:8px;font-size:.87rem;line-height:1.5;color:#526078}.df-step-details li>span{font-weight:700;color:var(--step-color);min-width:25px}.df-tool-links{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:24px}.df-tool-links>a{border:1px solid #dce5f0;border-radius:15px;background:#fff;padding:21px 23px;display:flex;align-items:center;gap:15px;color:#1e467a;text-decoration:none;font-weight:600}.df-tool-links>a>span{flex:1}.df-tool-links small{display:block;font-weight:400;color:#768197;margin-top:5px}.df-list-table th{background:#f5f7fb;padding:16px 18px;color:#68768d;font-size:.76rem;text-transform:uppercase;letter-spacing:.06em}.df-list-table td{padding:20px 18px;border-color:#edf0f5}.df-list-table td:first-child{width:29%}.df-list-code{font-size:1.02rem;font-weight:700;color:#163b6d}.df-progress-badges{display:flex;gap:7px;flex-wrap:wrap}.df-progress-badges span{font-size:.71rem;padding:4px 8px;background:#f0f3f7;border:1px solid #e2e7ef;border-radius:6px;color:#6a7688}.df-progress-badges .is-saved{background:#e8f6ed;border-color:#c7e7d2;color:#2d7049}
@media(min-width:1500px){.df-workflow{gap:40px}.df-step-circle{padding:38px}.df-step-title{font-size:1.5rem}}
@media(max-width:1000px){.df-page-hero{align-items:flex-start;flex-direction:column}.df-workflow{grid-template-columns:repeat(2,minmax(0,1fr));gap:32px}.df-step-circle{max-width:330px;margin:auto}.df-workflow-step:nth-child(2) .df-step-circle:after{display:none}.df-step-title{font-size:1.25rem}.df-tool-links{grid-template-columns:1fr}.df-section-heading{align-items:flex-start;flex-direction:column;gap:12px}}
@media(max-width:575px){.df-workspace{padding-left:12px;padding-right:12px}.df-page-hero{padding:24px;border-radius:15px}.df-workflow-panel{padding:22px 18px}.df-workflow{grid-template-columns:1fr;gap:35px}.df-workflow-step .df-step-circle:after{display:none}.df-step-circle{width:240px}.df-section-heading>.btn{width:100%}.df-list-table td{min-width:170px}.df-company-context{padding:16px 4px}}
.df-progress-table-wrap{border:1px solid #e1e7ef;border-radius:10px}.df-progress-table{min-width:1620px;border-color:#e1e7ef;font-size:.82rem}.df-progress-table thead th{padding:12px 8px;vertical-align:middle;white-space:nowrap;font-size:.7rem;letter-spacing:.035em}.df-progress-table thead .df-progress-group{background:#eaf0f8;color:#25466f}.df-progress-table tbody td{padding:16px 8px;vertical-align:middle}.df-progress-table .df-company-column{width:auto;min-width:140px;max-width:200px}.df-progress-table .df-code-column{min-width:165px}.df-progress-table .df-list-code{font-size:.87rem}.df-progress-table .df-factor-column{min-width:56px}.df-progress-table .df-step-column{min-width:110px;background:#f8fafd}.df-progress-table .df-date-column{min-width:120px;white-space:nowrap;color:#65738a}.df-progress-table time small{display:block;color:#8994a5;font-size:.7rem;margin-top:3px}.df-progress-table .df-actions-column{min-width:185px}.df-answer-progress,.df-save-status{display:inline-block;border:1px solid transparent;border-radius:6px;padding:5px 6px;font-size:.73rem;font-weight:600;line-height:1.3;white-space:nowrap;font-variant-numeric:tabular-nums}.df-answer-progress{min-width:39px}.df-progress-table .is-empty{color:#8590a0;background:#f0f3f7;border-color:#e4e9f0}.df-progress-table .is-partial{color:#8a671c;background:#fff7df;border-color:#f0e1b5}.df-progress-table .is-complete{color:#287047;background:#eaf7ee;border-color:#c9e8d3}
.df-list-table.df-progress-table td:first-child{width:auto}
</style>
